import React, { FormEvent } from 'react';

import cn from 'clsx';
import clsx from 'clsx';
import * as L from 'leaflet';

import { stringToColour } from '@helpers/colorsizeStringHelper';
import { getDefaultTileLayer, getMap, setDefaultMapView } from '@helpers/leafletHelper';
import notificationHelper, { warn } from '@helpers/notificationHelper';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
// eslint-disable-next-line import/order
import PohRow from '@ui-kit/layout/Row';

import 'leaflet/dist/leaflet.css';

import PohSelect from '@ui-kit/Select';

import style from '../../Hiking/tracks/HikingTracks/styel.module.less';
import { editWorkout, getOneWorkout, getWorkoutTypes } from '../@services/workouts.service';
import { IWorkoutEditDTO } from '../@types/DTO/workouts.dto.types';
import { IWorkoutType } from '../@types/workouts.types';
const startIcon = L.divIcon({
  className: clsx(style.icon, style.iconStart),
  html: '1',
  iconSize: [16, 16],
  iconAnchor: [8, 8],
});
const endIcon = L.divIcon({
  className: clsx(style.icon, style.iconEnd),
  html: '2',
  iconSize: [16, 16],
  iconAnchor: [8, 8],
});

const WorkoutEdit: React.FC<{ id: number }> = ({ id }) => {
  const mapContainerRef = React.useRef<HTMLDivElement>(null);
  const mapRef = React.useRef<L.Map>(null);
  const [formData, setFormData] = React.useState<IWorkoutEditDTO>({
    id,
    workout_type: 3,
    name: '',
    description: '',
  });

  const [types, setTypes] = React.useState<IWorkoutType[]>([]);
  const [origName, setOrigName] = React.useState('');
  React.useEffect(() => {
    getWorkoutTypes().then(setTypes);
  }, []);

  React.useEffect(() => {
    getOneWorkout(id).then((oneWorkout) => {
      setFormData((cur) => ({
        ...cur,
        workout_type: oneWorkout.type.id,
        name: oneWorkout.name,
        description: oneWorkout.description,
      }));
      setOrigName(oneWorkout.name);

      if (mapRef.current) {
        new L.Marker(oneWorkout.track[0].point, {
          icon: startIcon,
        }).addTo(mapRef.current);

        new L.Marker(oneWorkout.track[oneWorkout.track.length - 1].point, {
          icon: endIcon,
        }).addTo(mapRef.current);

        const pl = new L.Polyline(
          oneWorkout.track.map((p) => p.point),
          { color: stringToColour(oneWorkout.name) },
        );
        pl.addTo(mapRef.current);
        mapRef.current.fitBounds(pl.getBounds());
      }
    });
  }, [id]);

  React.useEffect(() => {
    if (!mapContainerRef.current) return;
    mapRef.current = getMap(mapContainerRef.current, {
      fullscreenControl: true,
    });

    getDefaultTileLayer().addTo(mapRef.current);
    setDefaultMapView(mapRef.current);
  }, [mapContainerRef, mapRef]);

  const handleInputChange =
    <K extends keyof IWorkoutEditDTO>(field: keyof IWorkoutEditDTO) =>
    (value: IWorkoutEditDTO[K]) => {
      setFormData((fd) => ({
        ...(fd as IWorkoutEditDTO),
        [field]: value,
      }));
    };

  const submitFormHandler = (e: FormEvent) => {
    e.preventDefault();

    editWorkout(formData).then(() => {
      notificationHelper.success('Тренировка обновлена');
    });
  };

  return (
    <section>
      <>
        <Breadcrumb
          data={[
            { href: `/workouts`, text: 'Тренировки' },
            { href: `/workouts/${id}`, text: origName },
            { href: `/workouts/${id}/edit`, text: 'Редактирование тренировки', active: true },
          ]}
        />
        <PohContainer>
          <PohRow>
            <PohCol sm={12}>
              <div className="float-end d-flex" style={{ gap: '8px' }}>
                <PohButton
                  disabled
                  size={ButtonSize.Small}
                  variant={ButtonVariant.Light}
                  onClick={() => warn('Пока не работает')}
                >
                  Редактировать трек
                </PohButton>
              </div>
              <h3 className="mb-3">{origName}</h3>
            </PohCol>
          </PohRow>
          <PohRow>
            <PohCol sm={12}>
              <div ref={mapContainerRef} style={{ height: '320px' }} />
            </PohCol>
          </PohRow>
          <PohRow>
            <PohCol md={{ offset: 2 }}>
              <div>
                <form
                  onSubmit={submitFormHandler}
                  className={cn('mt-4', 'qa-hiking-base-info-form')}
                >
                  <PohRow className="mb-2">
                    <PohCol sm={12}>
                      <PohSelect
                        horizontal
                        label="Тип"
                        placeholder="Тип тренировки"
                        required
                        value={formData.workout_type}
                        name="workout-type"
                        id="workout-type"
                        allowEmpty
                        options={
                          types ? types.map(({ id: value, name }) => ({ label: name, value })) : []
                        }
                        onChange={handleInputChange<'workout_type'>('workout_type')}
                        disabled={!types}
                      />
                    </PohCol>
                  </PohRow>
                  <PohRow className="mb-2">
                    <PohCol sm={12}>
                      <PohInput
                        horizontal
                        label="Название"
                        placeholder="Название тренировки"
                        required
                        value={formData.name}
                        name="workout-name"
                        autoComplete="workout-name"
                        id="workout-name"
                        onChange={handleInputChange<'name'>('name')}
                        autoFocus
                      />
                    </PohCol>
                  </PohRow>
                  <PohRow className="mb-2">
                    <PohCol sm={12}>
                      <PohInput
                        horizontal
                        type={InputTypes.textarea}
                        label="Описание"
                        placeholder="Краткое описание тренировки"
                        value={formData.description}
                        name="workout-desc"
                        autoComplete="workout-desc"
                        id="workout-desc"
                        onChange={handleInputChange<'description'>('description')}
                      />
                    </PohCol>
                  </PohRow>
                  <PohRow className="mb-4 mt-2">
                    <PohCol sm={2} />
                    <PohCol sm={10}>
                      <PohButton variant={ButtonVariant.Primary} className="w-100" type="submit">
                        Сохранить
                      </PohButton>
                    </PohCol>
                  </PohRow>
                </form>
              </div>
            </PohCol>
          </PohRow>
        </PohContainer>
      </>
    </section>
  );
};

export default WorkoutEdit;
